def run_hello_seeding():
    print("🚀 Running Hello Tenant Database Seeding...")

    # 1. Connect to postgres database to create tenant database if it doesn't exist
    pg_url = f"postgresql://{settings.DB_USER}:{settings.DB_PASSWORD}@{settings.DB_HOST}:{settings.DB_PORT}/postgres"
    pg_engine = create_engine(pg_url, isolation_level="AUTOCOMMIT")
    
    with pg_engine.connect() as conn:
        result = conn.execute(text("SELECT 1 FROM pg_database WHERE datname='crediiflow_hello'"))
        if not result.fetchone():
            print("Creating tenant database 'crediiflow_hello'...")
            conn.execute(text("CREATE DATABASE crediiflow_hello"))
        else:
            print("Database 'crediiflow_hello' already exists.")

    # 2. Register Tenant in master DB
    master_db = MasterSessionLocal()
    try:
        tenant = master_db.query(Tenant).filter(Tenant.subdomain == "hello").first()
        if not tenant:
            print("Registering Tenant 'hello' in master DB...")
            tenant = Tenant(
                name="HELLO",
                subdomain="hello",
                db_name="crediiflow_hello",
                status="active"
            )
            master_db.add(tenant)
            master_db.commit()
            print("Tenant 'hello' registered.")
        else:
            print("Tenant 'hello' already registered in master DB.")
    finally:
        master_db.close()

    # 3. Initialize tenant tables inside 'crediiflow_hello'
    tenant_url = get_tenant_connection_string("crediiflow_hello")
    tenant_engine = create_engine(tenant_url)
    print("Initializing tenant tables inside 'crediiflow_hello'...")
    Base.metadata.create_all(bind=tenant_engine)
    print("Tenant tables initialized.")

    # 4. Seed Admin/Staff and Retailers
    TenantSession = sessionmaker(bind=tenant_engine)
    tenant_db = TenantSession()
    try:
        # Check if admin already exists
        admin_exists = tenant_db.query(TenantUser).filter(TenantUser.phone == "7900671145").first()
        if not admin_exists:
            print("Seeding Tenant Admin for hello...")
            new_admin = TenantUser(
                name="Hello Admin",
                phone="7900671145",
                password_hash=get_password_hash("pass123"),
                role="admin"
            )
            tenant_db.add(new_admin)
            
        staff_exists = tenant_db.query(TenantUser).filter(TenantUser.phone == "9917128864").first()
        if not staff_exists:
            print("Seeding Tenant Staff for hello...")
            new_staff = TenantUser(
                name="Hello Staff",
                phone="9917128864",
                password_hash=get_password_hash("pass123"),
                role="staff"
            )
            tenant_db.add(new_staff)
        tenant_db.commit()

        # Delete any previously seeded incorrect retailers to allow fresh seeding
        print("Clearing previously seeded retailers (if any)...")
        tenant_db.query(Retailer).filter(Retailer.retailer_name != "CMS").delete()
        tenant_db.commit()

        print(f"Seeding {len(RETAILERS_TO_SEED)} retailers from PDF data...")
        for idx, r in enumerate(RETAILERS_TO_SEED):
            new_retailer = Retailer(
                retailer_name=r["name"],
                phone=r["phone"],
                address="New Delhi",
                opening_to_take=r["take"],
                opening_to_give=r["give"],
                balance=0.0
            )
            tenant_db.add(new_retailer)
        tenant_db.commit()
        print("Retailers committed. Now recalculating balances...")
        
        # Recalculate balances to create ledger entries
        retailers = tenant_db.query(Retailer).all()
        for r in retailers:
            recalculate_balances(r.id, tenant_db)
        tenant_db.commit()
        print("🎉 Seeding and balance recalculation for hello tenant complete!")
    finally:
        tenant_db.close()

if __name__ == "__main__":
    run_hello_seeding()
